import { Fragment } from "react";
import { Plus, Search, Filter, Trash2 } from "lucide-react";
import { Link } from "react-router-dom";

interface ArticleManagerToolbarProps {
  search: string;
  setSearch: (val: string) => void;
  statusFilter: string;
  setStatusFilter: (val: string) => void;
  categoryFilter: string;
  setCategoryFilter: (val: string) => void;
  sortFilter: string;
  setSortFilter: (val: string) => void;
  isTrashMode: boolean;
  setIsTrashMode: (val: boolean) => void;
  handleEmptyTrash: () => void;
  categories: any[];
}

export function ArticleManagerToolbarComponent({
  search,
  setSearch,
  statusFilter,
  setStatusFilter,
  categoryFilter,
  setCategoryFilter,
  sortFilter,
  setSortFilter,
  isTrashMode,
  setIsTrashMode,
  handleEmptyTrash,
  categories,
}: ArticleManagerToolbarProps) {
  const renderCategoryOptions = (nodes: any[], level = 0) => {
    return nodes.map((node) => {
      const indent = "— ".repeat(level);
      return (
        <Fragment key={node._id}>
          <option value={node._id}>
            {indent} {node.name}
          </option>
          {node.children &&
            node.children.length > 0 &&
            renderCategoryOptions(node.children, level + 1)}
        </Fragment>
      );
    });
  };

  return (
    <div className="bg-white dark:bg-slate-900/50 backdrop-blur-md p-4 sm:p-6 rounded-2xl shadow-sm border border-gray-100 dark:border-slate-800 flex flex-col md:flex-row gap-4 items-stretch md:items-center justify-between">
      <div className="flex flex-col sm:flex-row flex-1 gap-3 w-full md:w-auto">
        <div className="relative w-full sm:w-[250px] lg:w-[300px]">
          <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
            <Search size={18} className="text-gray-400" />
          </div>
          <input
            type="text"
            placeholder="Tìm kiếm tiêu đề bài viết..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-full pl-10 pr-4 py-2 border border-gray-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
          />
        </div>

        <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-2 w-full sm:w-auto">
          <div className="flex items-center gap-2 bg-white dark:bg-slate-800 backdrop-blur-md px-3 py-2 rounded-xl border border-gray-200 dark:border-slate-700 w-full sm:w-auto">
            <Filter
              size={18}
              className="text-gray-400 hidden sm:block shrink-0"
            />
            <select
              value={categoryFilter}
              onChange={(e) => setCategoryFilter(e.target.value)}
              className="bg-transparent dark:bg-slate-800 border-none text-sm outline-none focus:ring-0 w-full max-w-full sm:max-w-[150px] truncate cursor-pointer"
            >
              <option value="ALL">Tất cả danh mục</option>
              <option value="NONE">-- Không có danh mục --</option>
              <optgroup label="DỊCH VỤ & GIẢI PHÁP (SERVICE)">
                {renderCategoryOptions(
                  categories.filter((c) => c.type === "SERVICE"),
                )}
              </optgroup>
              <optgroup label="BÀI VIẾT & CẨM NANG (POST)">
                {renderCategoryOptions(
                  categories.filter((c) => c.type === "POST"),
                )}
              </optgroup>
              <optgroup label="GIỚI THIỆU (ABOUT)">
                {renderCategoryOptions(
                  categories.filter((c) => c.type === "ABOUT"),
                )}
              </optgroup>
            </select>
          </div>

          <select
            value={isTrashMode ? "ALL" : statusFilter}
            onChange={(e) => setStatusFilter(e.target.value)}
            disabled={isTrashMode}
            className="px-4 py-2 border border-gray-200 dark:border-slate-700 rounded-xl text-sm outline-none focus:ring-2 focus:ring-blue-500 bg-white dark:bg-slate-800 backdrop-blur-md w-full sm:w-auto disabled:opacity-50 cursor-pointer"
          >
            <option value="ALL">Tất cả trạng thái</option>
            <option value="PUBLISHED">Đã xuất bản</option>
            <option value="DRAFT">Bản nháp</option>
          </select>

          <select
            value={sortFilter}
            onChange={(e) => setSortFilter(e.target.value)}
            className="px-4 py-2 border border-gray-200 dark:border-slate-700 rounded-xl text-sm outline-none focus:ring-2 focus:ring-blue-500 bg-white dark:bg-slate-800 backdrop-blur-md w-full sm:w-auto cursor-pointer"
          >
            <option value="newest">Mới nhất</option>
            <option value="oldest">Cũ nhất</option>
            <option value="views">Lượt xem</option>
          </select>
        </div>
      </div>

      <div className="flex gap-2 w-full md:w-auto shrink-0 mt-4 md:mt-0 flex-wrap justify-start md:justify-end">
        <button
          onClick={() => setIsTrashMode(!isTrashMode)}
          className={`px-4 py-2.5 rounded-xl font-semibold text-sm flex items-center justify-center gap-2 transition-all w-full sm:w-auto shrink-0 ${isTrashMode ? "bg-red-50 text-red-600 hover:bg-red-100 dark:bg-red-900/30 dark:text-red-400" : "bg-gray-100 text-gray-700 hover:bg-gray-200 dark:bg-slate-800 dark:text-gray-200 dark:hover:bg-slate-700"}`}
        >
          <Trash2 size={18} />
          <span>{isTrashMode ? "Quay lại" : "Thùng rác"}</span>
        </button>

        {isTrashMode && (
          <button
            onClick={handleEmptyTrash}
            className="px-4 py-2.5 rounded-xl font-semibold text-sm flex items-center justify-center gap-2 border border-red-200 text-red-600 hover:bg-red-50 dark:border-red-900 dark:text-red-400 dark:hover:bg-red-900/30 transition-all w-full sm:w-auto shrink-0"
          >
            <Trash2 size={18} />
            <span>Dọn dẹp</span>
          </button>
        )}
        <Link
          to="/articles/new"
          className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2.5 rounded-xl font-semibold text-sm flex items-center justify-center gap-2 shadow-md hover:shadow-lg transition-all w-full sm:w-auto shrink-0"
        >
          <Plus size={18} />
          <span>Thêm Bài Viết</span>
        </Link>
      </div>
    </div>
  );
}
